PRAGMA foreign_keys=ON;
CREATE TABLE users(id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL, full_name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE properties(id INTEGER PRIMARY KEY, name TEXT NOT NULL, address TEXT NOT NULL, property_type TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE units(id INTEGER PRIMARY KEY, property_id INTEGER NOT NULL REFERENCES properties(id), unit_number TEXT NOT NULL, bedrooms INTEGER NOT NULL DEFAULT 0, monthly_rent REAL NOT NULL CHECK(monthly_rent>=0), status TEXT NOT NULL CHECK(status IN ('Vacant','Occupied','Under Maintenance')), UNIQUE(property_id,unit_number));
CREATE TABLE tenants(id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id), full_name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE leases(id INTEGER PRIMARY KEY, unit_id INTEGER NOT NULL REFERENCES units(id), tenant_id INTEGER NOT NULL REFERENCES tenants(id), start_date TEXT NOT NULL, end_date TEXT NOT NULL, monthly_rent REAL NOT NULL CHECK(monthly_rent>=0), status TEXT NOT NULL CHECK(status IN ('Pending','Active','Expired','Terminated')), approved_by INTEGER REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(end_date>=start_date));
CREATE TABLE payments(id INTEGER PRIMARY KEY, lease_id INTEGER NOT NULL REFERENCES leases(id), amount REAL NOT NULL CHECK(amount>0), due_date TEXT NOT NULL, paid_date TEXT, payment_method TEXT, reference_no TEXT, status TEXT NOT NULL CHECK(status IN ('Unpaid','Paid','Overdue')), recorded_by INTEGER REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE maintenance_requests(id INTEGER PRIMARY KEY, unit_id INTEGER NOT NULL REFERENCES units(id), tenant_id INTEGER REFERENCES tenants(id), title TEXT NOT NULL, description TEXT NOT NULL, priority TEXT NOT NULL CHECK(priority IN ('Low','Normal','High','Urgent')), status TEXT NOT NULL CHECK(status IN ('Pending','Assigned','In Progress','Completed','Rejected')), assigned_to INTEGER REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT);
CREATE TABLE utility_bills(id INTEGER PRIMARY KEY, unit_id INTEGER NOT NULL REFERENCES units(id), bill_type TEXT NOT NULL, amount REAL NOT NULL CHECK(amount>=0), due_date TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('Unpaid','Paid','Overdue')));
CREATE TABLE notices(id INTEGER PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, audience TEXT NOT NULL DEFAULT 'All', created_by INTEGER REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs(id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id), username TEXT, action TEXT NOT NULL, entity TEXT, entity_id INTEGER, details TEXT, ip_address TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
